import type { I18n, MessageDescriptor } from "@lingui/core";
import { msg } from "@lingui/core/macro";
import type { z } from "zod";

/**
 * Form metadata on zod fields (`.meta(field({...}))`), shared by driver
 * registries whose config forms are generated (backup destinations,
 * notification channels). Client-safe.
 */
export interface FieldMeta {
	label: MessageDescriptor;
	help?: MessageDescriptor;
	placeholder?: string;
	/** Stored encrypted, masked when read back, never logged. */
	secret?: boolean;
	/** Generated by the server (not typed in the form; e.g. signing keys). */
	generated?: boolean;
	/** Multi-line input. */
	multiline?: boolean;
	/** Choices of an enum field (value → label). */
	options?: { value: string; label: MessageDescriptor }[];
}

/** zod `.meta()` payload (its own `description` key is a plain string). */
export const field = (meta: FieldMeta) =>
	({ ...meta }) as Record<string, unknown>;

export interface SchemaField {
	name: string;
	kind: "string" | "boolean" | "number" | "enum";
	required: boolean;
	/** Schema default (e.g. a switch's initial state). */
	defaultValue: unknown;
	meta: FieldMeta;
}

/** Form fields of an object schema, from its shape and `.meta()`. */
export function schemaFields(schema: z.ZodObject): SchemaField[] {
	return Object.entries(schema.shape).map(([name, entry]) => {
		const type = entry as z.ZodType;
		const meta = (type.meta() ?? {}) as unknown as FieldMeta;
		const empty = type.safeParse(undefined);
		// Coercing number schemas accept `true` too: test numbers first.
		const kind = meta.options
			? "enum"
			: type.safeParse(5).success && !type.safeParse("x").success
				? "number"
				: type.safeParse(true).success
					? "boolean"
					: "string";
		return {
			name,
			kind,
			required: !empty.success,
			defaultValue: empty.success ? empty.data : undefined,
			meta,
		};
	});
}

export function secretFieldNames(schema: z.ZodObject): string[] {
	return schemaFields(schema)
		.filter((item) => item.meta.secret)
		.map((item) => item.name);
}

/** Descriptors of every validation message, by id (see `validation`). */
const validationMessages = new Map<string, MessageDescriptor>();

/**
 * A validation message for a driver schema: zod takes a string, so the
 * descriptor is registered and its id stored in the issue; the UI turns it
 * back into the descriptor with `validationMessage` (no dynamic `i18n._`).
 */
export const validation = (descriptor: MessageDescriptor): string => {
	validationMessages.set(descriptor.id, descriptor);
	return descriptor.id;
};

/**
 * Translated text of a message from `schemaIssues` (a registered validation
 * id). Anything else is shown as is.
 */
export function validationMessage(i18n: I18n, message: string): string {
	const descriptor = validationMessages.get(message);
	return descriptor ? i18n._(descriptor) : message;
}

const REQUIRED = msg({ id: "This field is required" });
const INVALID = msg({ id: "Invalid value" });
const INVALID_URL = msg({ id: "Enter a valid URL" });
const INVALID_EMAIL = msg({ id: "Enter a valid email address" });
for (const descriptor of [REQUIRED, INVALID, INVALID_URL, INVALID_EMAIL]) {
	validation(descriptor);
}

/**
 * Params of cross-field refinements (`.superRefine(fn, crossField)`): they
 * also run when another field is invalid (e.g. a secret kept on edit), so a
 * form shows every problem at once. The refinement must tolerate partial
 * input (check types first).
 */
export const crossField = {
	when: (payload: { value: unknown }) =>
		typeof payload.value === "object" && payload.value !== null,
};

/**
 * First validation message per form field (message ids, translate with
 * `validationMessage`). Issues zod generates itself map to generic messages; empty
 * values report "required".
 */
function schemaIssues(
	schema: z.ZodType,
	values: Record<string, unknown>,
): Record<string, string> {
	const parsed = schema.safeParse(values);
	if (parsed.success) return {};
	const errors: Record<string, string> = {};
	for (const issue of parsed.error.issues) {
		const name = String(issue.path[0] ?? "");
		if (!name || errors[name]) continue;
		const value = values[name];
		const empty = value === undefined || value === null || value === "";
		const generic =
			issue.code === "invalid_format"
				? (issue as { format?: string }).format === "url"
					? INVALID_URL.id
					: (issue as { format?: string }).format === "email"
						? INVALID_EMAIL.id
						: null
				: null;
		errors[name] = empty
			? REQUIRED.id
			: issue.code === "custom" || (issue.code === "invalid_format" && !generic)
				? issue.message
				: (generic ?? INVALID.id);
	}
	return errors;
}

/**
 * `schemaIssues` for a generated form: generated fields and (when editing)
 * secrets left empty to keep the stored value are not reported.
 */
export function formIssues(
	schema: z.ZodObject,
	values: Record<string, unknown>,
	options: { editing?: boolean; secretMask?: string } = {},
): Record<string, string> {
	const skip = new Set(
		schemaFields(schema)
			.filter(
				(item) =>
					item.meta.generated ||
					(options.editing &&
						item.meta.secret &&
						(values[item.name] === undefined ||
							values[item.name] === "" ||
							values[item.name] === options.secretMask)),
			)
			.map((item) => item.name),
	);
	return Object.fromEntries(
		Object.entries(schemaIssues(schema, values)).filter(
			([name]) => !skip.has(name),
		),
	);
}

/** Server-side fallback text of a failed parse: "<field label>: <message>". */
export function describeSchemaError(
	_schema: z.ZodObject,
	error: z.ZodError,
): { field: string; detail: string } {
	const issue = error.issues[0];
	return {
		field: String(issue?.path[0] ?? ""),
		detail: issue?.message ?? "",
	};
}

export { isPrivateHost } from "./ip-ranges";
